var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('parse regexp must be anchored at the start', function () {
    // Correct bytes@3.1.2 behaviour: parse() must match the whole string;
    // otherwise it falls back to parseInt()/null handling. With the '^'
    // anchor removed from parseRegExp, a trailing number+unit suffix is
    // silently parsed instead: parse('foo1kb') must be null (not 1024),
    // parse('.5kb') must be null (not 5120) and parse('1kb2gb') must be
    // 1 (not 2147483648).
    assert.strictEqual(bytes.parse('foo1kb'), null);
    assert.strictEqual(bytes.parse('.5kb'), null);
    assert.strictEqual(bytes.parse('1kb2gb'), 1);
  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('parses multi-digit values with units', function () {
    assert.strictEqual(bytes('10kb'), 10240);
  });

  it('parses large multi-digit values with units', function () {
    assert.strictEqual(bytes.parse('1024mb'), 1073741824);
  });

  it('parses negative multi-digit values with units', function () {
    assert.strictEqual(bytes.parse('-10kb'), -10240);
  });

  it('parses multi-digit decimal values with units', function () {
    assert.strictEqual(bytes.parse('10.5kb'), 10752);
  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('keeps the default of 2 decimal places when options omit decimalPlaces', function () {
    // fixedDecimals keeps the raw toFixed output, exposing the precision used
    assert.strictEqual(bytes(1024, { fixedDecimals: true }), '1.00KB');

    // default of 2 places: 1.5KB; with 0 places (toFixed(undefined)) this becomes 2KB
    assert.strictEqual(bytes(1536, {}), '1.5KB');
    assert.strictEqual(bytes(1536, { decimalPlaces: undefined }), '1.5KB');
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('resolves an explicit !!int tag on unsigned octal', () => {
    // Implicit unsigned octal is accepted by the core int pattern...
    assert.strictEqual(load('0o777'), 511);
    // ...so an explicit !!int tag must accept it too. The core explicit int
    // pattern requires a sign on octal ([-+]0o instead of [-+]?0o), unlike
    // the JSON variant, so this throws on the patched build:
    assert.strictEqual(load('!!int 0o777'), 511);
    assert.strictEqual(load('!!int 0o0'), 0);
    assert.strictEqual(dump(load('!!int 0o777')), '511\n');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('rejects null with the documented Error and never parses non-strings', function () {
    // The string type-check must short-circuit before `.length` is read;
    // otherwise ms(null) throws a TypeError instead of the library's Error.
    assert.throws(function () { ms(null); }, /val is not a non-empty string/);

    // A non-string value that happens to have a length (e.g. an array)
    // must be rejected, not silently parsed as a duration.
    assert.throws(function () { ms(['100']); });
  });
});

